function isAnagram(a, b) {
  const bersih = s => s.toLowerCase().replace(/ /g, "");
  a = bersih(a); b = bersih(b);
  if (a.length !== b.length) return false;
  const hitung = {};
  for (const ch of a) hitung[ch] = (hitung[ch] || 0) + 1;
  for (const ch of b) {
    if (!hitung[ch]) return false;
    hitung[ch]--;
  }
  return true;
}

